import{_ as e,o as t,c as a,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2020-02-05 :: Ceph Developer Monthly","description":"","frontmatter":{"title":"2020-02-05 :: Ceph Developer Monthly","date":"2020-02-05T00:00:00.000Z","updated":"2020-04-04T00:00:00.000Z","tags":["Ceph","分布式存储","CRUSH算法","监控系统","自动化部署","功能开发","用户启用"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/2020-02-05_-_-_Ceph_Developer_Monthly.md","filePath":"posts/2020/2020-02-05_-_-_Ceph_Developer_Monthly.md","lastUpdated":1780460162000}'),o={name:"posts/2020/2020-02-05_-_-_Ceph_Developer_Monthly.md"};function r(n,l,s,h,p,_){return t(),a("div",null,[...l[0]||(l[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>: 2020年2月5日</li><li><strong>参与者</strong>: Liam, Josh, 及其他相关人员</li><li><strong>主要议题</strong>: Ceph项目状态更新、功能开发进展、监控系统改进、自动化部署及未来计划</li></ul><h4 id="讨论内容" tabindex="-1">讨论内容 <a class="header-anchor" href="#讨论内容" aria-label="Permalink to &quot;讨论内容&quot;">​</a></h4><ol><li><p><strong>状态更新</strong></p><ul><li>目前主要进行的是一些小的修复和改进，包括监控系统的进展，如添加节点导出器和Prometheus的工作正在进行中。</li><li>部署FSS（文件系统存储）的工作也在进行中，但还有一些紧急问题需要解决，特别是在orchestrator模块中。</li></ul></li><li><p><strong>监控系统改进</strong></p><ul><li>讨论了如何处理主机和主机名的模糊性问题，提出了确保主机名一致性的方案，以便更好地集成到CRUSH map中。</li><li>需要增加基于每个主机的IP或完全限定域名的能力，以便在不依赖DNS的情况下进行通信。</li></ul></li><li><p><strong>自动化部署</strong></p><ul><li>讨论了Ansible playbook的使用，用于自动化Ceph集群的部署和转换过程。</li><li>强调了在监控方面和故障处理方面仍存在的主要差距。</li></ul></li><li><p><strong>功能开发进展</strong></p><ul><li>讨论了NFS网关的开发状态，目前仍在进行中，但尚未有人关注rgw NFS网关。</li><li>密码更改功能即将完成，正在进行最后的QA测试。</li></ul></li><li><p><strong>未来计划</strong></p><ul><li>计划在接下来的一个月内推动用户启用telemetry模块，目标是达到500或1000个活跃的集群。</li><li>讨论了关于cephal的在线会议计划，建议分块进行，以便更有效地讨论各个议题。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了Ceph集群的监控和自动化部署的改进方向。</li><li>确定了密码更改功能的最终测试和部署计划。</li><li>计划推动用户启用telemetry模块，并设定了具体的目标。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续推进监控系统和自动化部署的改进工作。</li><li>完成密码更改功能的QA测试并部署。</li><li>推动用户启用telemetry模块，并通过邮件列表和社交媒体进行宣传。</li><li>安排cephalic的在线会议，分块讨论各个议题。</li></ul><h4 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h4><ul><li>讨论了关于Ceph客户端版本和功能比特的命名问题，建议未来不再使用命名版本，而是直接使用功能比特来标识支持的功能。</li></ul><p>会议结束时，所有参与者对未来的工作计划表示了肯定，并期待下一次的在线会议。</p>',12)])])}const c=e(o,[["render",r]]);export{d as __pageData,c as default};
